<?php
declare(strict_types=1);
require __DIR__ . '/config.php';
require_login();
require __DIR__ . '/patient-layout.php';
$pdo=db();$sqlite=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite';
$pdo->exec($sqlite?'CREATE TABLE IF NOT EXISTS current_accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, title TEXT NOT NULL, account_type TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP)':'CREATE TABLE IF NOT EXISTS current_accounts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, title VARCHAR(190) NOT NULL, account_type ENUM("customer","supplier","both") NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
$pdo->exec($sqlite?'CREATE TABLE IF NOT EXISTS stock_movements (id INTEGER PRIMARY KEY AUTOINCREMENT, stock_id INTEGER NOT NULL, movement_type TEXT NOT NULL, quantity INTEGER NOT NULL, movement_date TEXT NOT NULL, description TEXT, current_account_id INTEGER NULL, invoice_no TEXT NULL, serial_numbers TEXT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP)':'CREATE TABLE IF NOT EXISTS stock_movements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, stock_id INT UNSIGNED NOT NULL, movement_type VARCHAR(30) NOT NULL, quantity INT NOT NULL, movement_date DATE NOT NULL, description TEXT NULL, current_account_id INT UNSIGNED NULL, invoice_no VARCHAR(100) NULL, serial_numbers TEXT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX stock_movements_stock_id (stock_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
function stock_entry_column(PDO $pdo,string $column):bool{$driver=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME);if($driver==='sqlite'){foreach($pdo->query('PRAGMA table_info(stock_movements)')->fetchAll() as $item)if($item['name']===$column)return true;return false;}$q=$pdo->prepare('SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name="stock_movements" AND column_name=?');$q->execute([$column]);return(bool)$q->fetchColumn();}
foreach(['current_account_id'=>'INTEGER NULL','invoice_no'=>'VARCHAR(100) NULL','serial_numbers'=>'TEXT NULL'] as $column=>$definition)if(!stock_entry_column($pdo,$column))$pdo->exec('ALTER TABLE stock_movements ADD COLUMN '.$column.' '.$definition);
$stocks=$pdo->query('SELECT id,stock_code,stock_name,serial_no,COALESCE(stock_type,"") AS stock_type FROM stock_cards ORDER BY stock_name,stock_code')->fetchAll();$accounts=$pdo->query("SELECT id,code,title FROM current_accounts WHERE account_type IN ('supplier','both') ORDER BY title")->fetchAll();$form=['stock_type'=>'','stock_id'=>'','current_account_id'=>'','invoice_no'=>'','quantity'=>'','movement_date'=>date('Y-m-d'),'description'=>''];$serials=[];$error='';$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)?:0;
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='delete'){verify_csrf();$deleteId=filter_var($_POST['movement_id']??null,FILTER_VALIDATE_INT);if($deleteId)$pdo->prepare('DELETE FROM stock_movements WHERE id=? AND movement_type="Giriş"')->execute([$deleteId]);header('Location: '.url('stock-entry.php?deleted=1'));exit;}
if($editId){$editStatement=$pdo->prepare('SELECT m.*,s.stock_type FROM stock_movements m INNER JOIN stock_cards s ON s.id=m.stock_id WHERE m.id=? AND m.movement_type="Giriş"');$editStatement->execute([$editId]);$editRecord=$editStatement->fetch();if(!$editRecord){http_response_code(404);exit('Stok girişi bulunamadı.');}foreach($form as $field=>$value)$form[$field]=(string)($editRecord[$field]??$value);$serials=json_decode((string)$editRecord['serial_numbers'],true)?:[];}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($form as $field=>$value)$form[$field]=trim((string)($_POST[$field]??$value));$stockId=filter_var($form['stock_id'],FILTER_VALIDATE_INT);$accountId=filter_var($form['current_account_id'],FILTER_VALIDATE_INT);$quantity=filter_var($form['quantity'],FILTER_VALIDATE_INT);$serials=array_values(array_filter(array_map('trim',(array)($_POST['serial_numbers']??[])),static fn($serial)=>$serial!==''));if(!in_array($form['stock_type'],['Kulaklık','Sarf Malzeme'],true)||!$stockId||!$accountId||!$quantity||$quantity<1)$error='Stok tipi, stok, cari ve giriş miktarı zorunludur.';elseif(count($serials)!==$quantity)$error='Giriş miktarı kadar seri numarası girin.';elseif(count($serials)!==count(array_unique($serials)))$error='Seri numaraları birbirinden farklı olmalıdır.';else{$check=$pdo->prepare('SELECT 1 FROM stock_cards WHERE id=? AND stock_type=?');$check->execute([$stockId,$form['stock_type']]);$accountCheck=$pdo->prepare('SELECT 1 FROM current_accounts WHERE id=?');$accountCheck->execute([$accountId]);if(!$check->fetchColumn()||!$accountCheck->fetchColumn())$error='Seçilen stok tipine uygun stok ve cari seçin.';else{if($editId)$pdo->prepare('UPDATE stock_movements SET stock_id=?,quantity=?,movement_date=?,description=?,current_account_id=?,invoice_no=?,serial_numbers=? WHERE id=? AND movement_type="Giriş"')->execute([$stockId,$quantity,$form['movement_date'],$form['description'],$accountId,$form['invoice_no'],json_encode($serials,JSON_UNESCAPED_UNICODE),$editId]);else $pdo->prepare('INSERT INTO stock_movements(stock_id,movement_type,quantity,movement_date,description,current_account_id,invoice_no,serial_numbers) VALUES(?,?,?,?,?,?,?,?)')->execute([$stockId,'Giriş',$quantity,$form['movement_date'],$form['description'],$accountId,$form['invoice_no'],json_encode($serials,JSON_UNESCAPED_UNICODE)]);header('Location: '.url('stock-entry.php?saved=1'));exit;}}}
if (!isset($_GET['new'])) { $movements=$pdo->query('SELECT m.*,s.stock_code,s.stock_name,s.stock_type,c.title AS account_title FROM stock_movements m INNER JOIN stock_cards s ON s.id=m.stock_id LEFT JOIN current_accounts c ON c.id=m.current_account_id WHERE m.movement_type="Giriş" ORDER BY m.movement_date DESC,m.id DESC')->fetchAll(); patient_header('Stok Girişi','stock'); ?>
<main class="patient-container stock-entry-list-page"><section class="technical-card"><header><h1><i class="ti tabler-package-import"></i> Stok Girişi</h1><p>Kaydedilen stok giriş hareketleri.</p><a class="button new-stock-entry" href="<?=e(url('stock-entry.php?new=1'))?>">+ Yeni Stok Girişi</a></header><div class="technical-table-wrap"><table><thead><tr><th>TARİH</th><th>STOK TİPİ</th><th>STOK KARTI</th><th>CARİ</th><th>FATURA NO</th><th>MİKTAR</th><th>İŞLEMLER</th></tr></thead><tbody><?php foreach($movements as $movement):?><tr><td><?=e(format_date_tr($movement['movement_date']))?></td><td><?=e($movement['stock_type']??'—')?></td><td><?=e($movement['stock_code'].' — '.$movement['stock_name'])?></td><td><?=e($movement['account_title']?:'—')?></td><td><?=e($movement['invoice_no']?:'—')?></td><td><?=e((string)$movement['quantity'])?></td><td><div class="entry-actions"><a href="<?=e(url('stock-entry.php?new=1&edit='.(int)$movement['id']))?>" title="Düzenle"><i class="ti tabler-pencil"></i></a><form method="post" onsubmit="return confirm('Bu stok girişi silinsin mi?');"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="movement_id" value="<?=$movement['id']?>"><button title="Sil"><i class="ti tabler-trash"></i></button></form></div></td></tr><?php endforeach;if(!$movements):?><tr><td class="empty" colspan="7">Henüz stok girişi bulunmuyor.</td></tr><?php endif?></tbody></table></div></section></main>
