<main class="patient-container stock-entry-page"><section class="vuexy-form-card stock-entry-card"><header class="form-card-title"><h1>Stok Girişi</h1><p>Stok kartına giriş hareketi ekleyin.</p></header><?php if($error):?><p class="stock-entry-error"><?=e($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Stok Tipi *<select id="entry-stock-type" name="stock_type" required><option value="">Seçiniz</option><option <?=$form['stock_type']==='Kulaklık'?'selected':''?>>Kulaklık</option><option <?=$form['stock_type']==='Sarf Malzeme'?'selected':''?>>Sarf Malzeme</option></select></label><label>Stok Kartı *<select id="entry-stock-card" name="stock_id" required><option value="">Önce stok tipi seçiniz</option><?php foreach($stocks as $stock):?><option data-stock-type="<?=e($stock['stock_type'])?>" value="<?=$stock['id']?>" <?=$form['stock_id']==$stock['id']?'selected':''?>><?=e($stock['stock_code'].' — '.$stock['stock_name'].' ('.$stock['serial_no'].')')?></option><?php endforeach?></select></label><label>Cari *<select name="current_account_id" required><option value="">Seçiniz</option><?php foreach($accounts as $account):?><option value="<?=$account['id']?>" <?=$form['current_account_id']==$account['id']?'selected':''?>><?=e($account['code'].' — '.$account['title'])?></option><?php endforeach?></select></label><label>Fatura No<input name="invoice_no" value="<?=e($form['invoice_no'])?>" maxlength="100"></label><label>Giriş Tarihi *<input type="date" name="movement_date" value="<?=e($form['movement_date'])?>" required></label><label>Giriş Miktarı *<input id="entry-quantity" type="number" min="1" name="quantity" value="<?=e($form['quantity'])?>" required></label><div class="stock-entry-wide serial-area"><strong>Seri Numaraları *</strong><div id="serial-fields"></div></div><label class="stock-entry-wide">Açıklama<textarea name="description" rows="3"><?=e($form['description'])?></textarea></label><footer><a href="<?=e(url('stocks.php'))?>">İptal</a><button class="button">Kaydet</button></footer></form></section></main>
<script>(()=>{const quantity=document.getElementById('entry-quantity'),box=document.getElementById('serial-fields'),type=document.getElementById('entry-stock-type'),stock=document.getElementById('entry-stock-card'),old=<?=json_encode($serials)?>;const filterStocks=()=>{[...stock.options].forEach(option=>{if(!option.dataset.stockType)return;option.hidden=option.dataset.stockType!==type.value});if(stock.selectedOptions[0]?.hidden)stock.value=''};const render=()=>{const n=Math.max(0,parseInt(quantity.value||0,10));const values=[...box.querySelectorAll('input')].map(i=>i.value);box.innerHTML='';for(let i=0;i<n;i++){const input=document.createElement('input');input.name='serial_numbers[]';input.placeholder='Seri No '+(i+1);input.required=true;input.value=values[i]??old[i]??'';box.append(input)}};type.addEventListener('change',()=>{stock.value='';filterStocks()});quantity.addEventListener('input',render);filterStocks();render()})();</script>
